//! Baseline P32 frontier: keep comparative claims fair, matched, and replayable.
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.baseline.counterfactual-integrity-card-1+json";
pub const BOUNDARY:&str="preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct BaselineArm4{pub arm_id:String,pub strategy:String,pub benchmark_digest:ContentHash,pub metric_milli:i64,pub uncertainty_milli:u64,pub policy_epoch:u64,pub evidence_state:String,pub matched:bool,pub negative_result:bool,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct CounterfactualIntegrityRequest4{pub request_id:String,pub purpose:String,pub arms:Vec<BaselineArm4>,pub required_arm_order:Vec<String>,pub required_strategy_order:Vec<String>,pub benchmark_digest:ContentHash,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:ContentHash,pub adversarial_events:Vec<String>,pub action_budget:u32,pub action_count:u32,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct CounterfactualIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub benchmark_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct CounterfactualIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub purpose:String,pub disposition:String,pub arm_order:Vec<String>,pub matched_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub strategy_order:Vec<String>,pub metric_order:Vec<String>,pub uncertainty_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub replay_identity:ContentHash,pub closure_digest:ContentHash,pub artifact:CounterfactualIntegrityArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum CounterfactualIntegrityError{#[error("invalid counterfactual-integrity request: {0}")]Invalid(String),#[error("counterfactual-integrity card failed validation: {0}")]Output(String)}
fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn nonempty(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":"1.0.0","capability_id":id,"version":version,"owner_crate":"baseline","consumers":["evaluation engine","experiment designer","interpretation compiler","release auditor"],"behavior":format!("qualify matched counterfactual baseline at {scale} ({mode})"),"value":"prevents unfair or incomparable baseline claims from masquerading as research advances","input_schema":"CounterfactualIntegrityRequest4@1","output_schema":"CounterfactualIntegrityCard7@1","effects":["emit:baseline-card","retain:negative-evidence","block:unfair-comparison"],"permissions":["read:local-benchmark"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
impl CounterfactualIntegrityCard7{pub fn validate(&self)->Result<(),CounterfactualIntegrityError>{if self.schema_version!="1.0.0"||!nonempty(&self.contract_version)||!nonempty(&self.feature_id)||!nonempty(&self.mode)||!nonempty(&self.scale)||!nonempty(&self.request_id)||!nonempty(&self.purpose)||self.boundary!=BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.arm_order.is_empty()||!ordered(&self.arm_order)||!ordered(&self.matched_order)||!ordered(&self.rejected_order)||!ordered(&self.unknown_order)||!ordered(&self.omitted_order)||!ordered(&self.strategy_order)||!ordered(&self.metric_order)||!ordered(&self.uncertainty_order)||!ordered(&self.negative_evidence_order)||!digest(&self.replay_identity)||!digest(&self.closure_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.closure_digest||self.artifact.boundary!=BOUNDARY{return Err(CounterfactualIntegrityError::Output("baseline identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.arm_order.iter().cloned());let states=self.matched_order.iter().chain(&self.rejected_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.arm_order.len()||states.len()!=ids.len()||BTreeSet::from_iter(states)!=ids{return Err(CounterfactualIntegrityError::Output("arm states do not partition".into()))}Ok(())}}
pub fn qualify(request:&CounterfactualIntegrityRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<CounterfactualIntegrityCard7,CounterfactualIntegrityError>{if !nonempty(&request.request_id)||!nonempty(&request.purpose)||request.arms.is_empty()||request.required_arm_order.is_empty()||request.required_strategy_order.is_empty()||!digest(&request.benchmark_digest)||!digest(&request.replay_identity)||request.boundary!=BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ordered(&request.required_arm_order)||!ordered(&request.required_strategy_order)||!ordered(&request.adversarial_events){return Err(CounterfactualIntegrityError::Invalid("baseline identity, requirements, digests, ordering, locality, or boundary is invalid".into()))}let mut rows=request.arms.clone();rows.sort_by(|a,b|a.arm_id.cmp(&b.arm_id));let mut seen=BTreeSet::new();let mut order=Vec::new();let mut matched=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut strategies=BTreeSet::new();let mut metrics=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();let mut benchmarks=BTreeSet::new();for a in &rows{if !seen.insert(a.arm_id.clone())||!nonempty(&a.arm_id)||!nonempty(&a.strategy)||!digest(&a.benchmark_digest)||!a.local||!a.aggregate_only{ return Err(CounterfactualIntegrityError::Invalid("arm identity, strategy, benchmark, or locality is invalid".into()))}order.push(a.arm_id.clone());strategies.insert(a.strategy.clone());metrics.insert(format!("{}:{}",a.arm_id,a.metric_milli));uncertainty.insert(format!("{}:{}",a.arm_id,a.uncertainty_milli));benchmarks.insert(a.benchmark_digest.clone());if a.negative_result{negative.insert(format!("{}:negative-result",a.arm_id));}if a.policy_epoch==0||a.evidence_state=="unknown"{unknown.insert(a.arm_id.clone());}else if !a.matched||a.benchmark_digest!=request.benchmark_digest||!request.required_strategy_order.contains(&a.strategy){rejected.insert(a.arm_id.clone());}else if a.benchmark_digest==request.replay_identity{omitted.insert(a.arm_id.clone());}else if !request.required_arm_order.contains(&a.arm_id){omitted.insert(a.arm_id.clone());}else{matched.insert(a.arm_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||request.action_count>request.action_budget;if global{omitted.extend(order.iter().cloned());matched.clear();rejected.clear();unknown.clear();}let missing=!request.required_arm_order.iter().all(|a|seen.contains(a))||!request.required_strategy_order.iter().all(|s|strategies.contains(s));let disposition=if global{"blocked"}else if missing{"unknown"}else if !rejected.is_empty()||!unknown.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let mut payload=json!({"schema_version":"1.0.0","contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"purpose":request.purpose,"disposition":disposition,"arm_order":order,"matched_order":matched.into_iter().collect::<Vec<_>>(),"rejected_order":rejected.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"strategy_order":strategies.into_iter().collect::<Vec<_>>(),"metric_order":metrics.into_iter().collect::<Vec<_>>(),"uncertainty_order":uncertainty.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let hash=ContentHash::of_value(&payload).map_err(|e|CounterfactualIntegrityError::Output(e.to_string()))?;payload["closure_digest"]=json!(hash);payload["artifact"]=json!({"artifact_id":format!("baseline-counterfactual:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":hash,"semantic_loss":payload["omitted_order"],"benchmark_digests":benchmarks.into_iter().collect::<Vec<_>>(),"boundary":BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:baseline-card:{}",request.request_id)]}else{vec!["block:unfair-comparison".to_string()]});let out:CounterfactualIntegrityCard7=serde_json::from_value(payload).map_err(|e|CounterfactualIntegrityError::Output(e.to_string()))?;out.validate()?;Ok(out)}
